import path from 'path';
import { run } from '../src/cli';

test('debug cli run after restore', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-debug3-'));
  const contentDir = path.join(dir, 'content');
  const outDir = path.join(dir, 'dist');
  fs.mkdirSync(contentDir, { recursive: true });
  fs.writeFileSync(path.join(contentDir, 'one.md'), '---\ntitle: One\n---\nFirst body.');
  fs.writeFileSync(path.join(contentDir, 'two.md'), '---\ntitle: Two\n---\nSecond body.');
  const spy = jest.spyOn(console, 'log').mockImplementation(() => {});
  try {
    run(['build', '--content', contentDir, '--output', outDir, '--incremental']);
    run(['build', '--content', contentDir, '--output', outDir, '--incremental']);
  } finally {
    spy.mockRestore();
  }
  const output = spy.mock.calls.map((c) => c.join(' ')).join('\n');
  process.stdout.write('OUTPUT: ' + JSON.stringify(output) + '\n');
});
EOF
